contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        require(true);

        uint balBefore = address(c).balance;

        c.SetMinSum(_val); if (__ESBMC_reverted()) return;

        uint storedMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        assert(storedMinSum == _val && balAfter == balBefore);
    }

    receive() external payable {}
}

