pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        vm.assume(true);
        uint balBefore = address(c).balance;
        try c.SetMinSum(_val) {} catch { return; }
        uint256 storedMinSum;
        try c.MinSum() returns (uint256 __r) { storedMinSum = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(storedMinSum == _val && balAfter == balBefore);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
